
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_mpw1b95_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_mpw1b95", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.040837044548517e+00, -2.984044232477907e+00, -2.904506387514337e+00, -2.794415399100785e+00, -2.644586641246227e+00, -2.445555115476087e+00, -2.190142997447746e+00, -1.878004865383197e+00, -1.521408964354658e+00, -1.147016035979996e+00, -7.825527000299410e-01, -5.450473755715313e-01, -4.544181527725338e-01, -3.719651649984366e-01, -2.713278564693821e-01, -1.747358449750239e-01, -1.004318596280269e-01, -3.400000980583851e-02, -8.698809244238757e-04, -2.172682134044626e-06]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


